/**
 * The canonical event union. Pattern:
 *
 * ```ts
 * function handle(ev: Event) {
 *   if (ev.kind === "client.added") {
 *     // ev.payload is ClientAddedPayload
 *   }
 * }
 * ```
 */
export type Event = {
  [K in EventKind]: EnvelopeFields & {
    readonly kind: K;
    readonly payload: EventPayloadByKind[K];
  };
}[EventKind];

/** Helper: extract the payload type for a given kind. */
export type PayloadOf<K extends EventKind> = EventPayloadByKind[K];

/** Helper: extract the event variant for a given kind. */
export type EventOf<K extends EventKind> = Extract<Event, { kind: K }>;

